    ('G8-B1', 55, 545, 'c4e0e11b29ba936a5eaf47460884f3ff', 'bedingung', 'faktor', null, $rbf${"bedingungen": [{"name": "verkleinert um mehr als 10 %", "pruefe": ["<", "$1", "0,9"], "zeige": ["*", "$1", 100], "hinweis": "Mit deinem Faktor bleiben {} % des Werts."}, {"name": "verkleinert um weniger als 20 %", "pruefe": [">", "$1", "0,8"], "zeige": ["*", "$1", 100], "hinweis": "Mit deinem Faktor bleiben {} % des Werts."}], "beispiel": ["0,85"], "gut": [["0,82"], ["7/8"]], "gegenbeispiele": [{"werte": ["0,95"], "verletzt": "verkleinert um mehr als 10 %"}, {"werte": ["0,8"], "verletzt": "verkleinert um weniger als 20 %"}, {"werte": ["1,15"], "verletzt": "verkleinert um mehr als 10 %"}, {"werte": [15], "verletzt": "verkleinert um mehr als 10 %"}]}$rbf$::jsonb, 'id.verhaeltnisse.prozent', $rbf$[]$rbf$::jsonb),
    ('G8-B2', 55, 546, '07d36b20fffedc703c194a0adfc33ffc', 'bedingung', 'vermindert', null, $rbf${"bedingungen": [{"name": "Rabatt mindestens 10 %", "pruefe": ["und", [">=", "$2", 10], ["<", "$2", 100]], "zeige": "$2", "hinweis": "Dein Rabatt ist {} %."}, {"name": "neuer Preis ist 60 €", "pruefe": ["=", ["/", ["*", "$1", ["-", 100, "$2"]], 100], 60], "zeige": ["/", ["*", "$1", ["-", 100, "$2"]], 100], "hinweis": "Mit deinen Zahlen kostet der Artikel danach {} €."}], "beispiel": [75, 20], "gut": [[80, 25], [100, 40], [120, 50]], "gegenbeispiele": [{"werte": [63, 5], "verletzt": "Rabatt mindestens 10 %"}, {"werte": [70, 20], "verletzt": "neuer Preis ist 60 €"}, {"werte": [60, 100], "verletzt": "Rabatt mindestens 10 %"}]}$rbf$::jsonb, 'id.verhaeltnisse.prozent', $rbf$[]$rbf$::jsonb),
    ('G8-B3', 55, 547, 'ac87af0017324dac45efd3d5f4ca234b', 'bedingung', 'mehrfach', null, $rbf${"bedingungen": [{"name": "beide Faktoren positiv", "pruefe": [">", ["min", "$alle"], 0], "zeige": ["min", "$alle"], "hinweis": "Dein kleinerer Faktor ist {}."}, {"name": "kein Faktor ist 0,5 oder 1", "pruefe": ["und", ["!=", "$1", "0,5"], ["!=", "$1", 1], ["!=", "$2", "0,5"], ["!=", "$2", 1]], "hinweis": "Einer deiner Faktoren ist 0,5 oder 1."}, {"name": "zusammen wird halbiert", "pruefe": ["=", ["*", "$1", "$2"], "0,5"], "zeige": ["*", "$1", "$2"], "hinweis": "Nacheinander ergeben deine Faktoren den Faktor {}."}], "beispiel": ["0,8", "0,625"], "gut": [[2, "0,25"], ["1,25", "0,4"]], "gegenbeispiele": [{"werte": [-1, "-0,5"], "verletzt": "beide Faktoren positiv"}, {"werte": [1, "0,5"], "verletzt": "kein Faktor ist 0,5 oder 1"}, {"werte": ["0,8", "0,6"], "verletzt": "zusammen wird halbiert"}, {"werte": ["0,25", "0,25"], "verletzt": "zusammen wird halbiert"}]}$rbf$::jsonb, 'id.verhaeltnisse.prozent', $rbf$[]$rbf$::jsonb),
    ('G8-B4', 55, 548, 'e504628a9eebb7651f016e3cdbfae105', 'bedingung', 'zurueck', null, $rbf${"bedingungen": [{"name": "beide größer als 0", "pruefe": [">", ["min", "$alle"], 0], "zeige": ["min", "$alle"], "hinweis": "Deine kleinere Zahl ist {}."}, {"name": "Endpreis gleich Anfangspreis", "pruefe": ["=", ["/", ["*", ["+", 100, "$1"], ["-", 100, "$2"]], 100], 100], "zeige": ["/", ["*", ["+", 100, "$1"], ["-", 100, "$2"]], 100], "hinweis": "Aus 100 € werden mit deinen Zahlen am Ende {} €."}], "beispiel": [25, 20], "gut": [[100, 50], [60, "37,5"]], "gegenbeispiele": [{"werte": [0, 0], "verletzt": "beide größer als 0"}, {"werte": [20, 20], "verletzt": "Endpreis gleich Anfangspreis"}, {"werte": [25, 25], "verletzt": "Endpreis gleich Anfangspreis"}]}$rbf$::jsonb, 'id.verhaeltnisse.prozent', $rbf$[]$rbf$::jsonb),
    ('G8-B5', 55, 549, '494773237b01b2d16544d6735f414b61', 'bedingung', 'formel', null, $rbf${"bedingungen": [{"name": "Zinssatz größer als 0", "pruefe": [">", "$1", 0], "zeige": "$1", "hinweis": "Dein Zinssatz ist {} %."}, {"name": "am Ende mehr als 1 100 €", "pruefe": [">", ["/", ["hoch", ["+", 100, "$1"], 2], 10], 1100], "zeige": ["/", ["hoch", ["+", 100, "$1"], 2], 10], "hinweis": "Nach zwei Jahren sind es bei dir {} €."}, {"name": "am Ende weniger als 1 200 €", "pruefe": ["<", ["/", ["hoch", ["+", 100, "$1"], 2], 10], 1200], "zeige": ["/", ["hoch", ["+", 100, "$1"], 2], 10], "hinweis": "Nach zwei Jahren sind es bei dir {} €."}], "beispiel": [5], "gut": [[9], ["7,5"]], "gegenbeispiele": [{"werte": [-205], "verletzt": "Zinssatz größer als 0"}, {"werte": [4], "verletzt": "am Ende mehr als 1 100 €"}, {"werte": [10], "verletzt": "am Ende weniger als 1 200 €"}]}$rbf$::jsonb, 'id.verhaeltnisse.prozent', $rbf$[]$rbf$::jsonb)
  ) x(k, e, r, mt, y, l, ma, o, regel, fb) loop
    select count(*) into n from schule.aufgabe where einheit_id = z.e and pool = 'uebung' and reihenfolge = z.r;
    if n <> 1 then fehler := fehler || format('%s: %s Übungsaufgaben an Einheit %s, Platz %s', z.k, n, z.e, z.r); continue; end if;
    select * into a from schule.aufgabe where einheit_id = z.e and pool = 'uebung' and reihenfolge = z.r;
    if md5(coalesce(a.frage->>'text', '')) <> z.mt or a.antworttyp is distinct from z.y or a.variante_gruppe is distinct from z.l
       or (z.ma is not null and md5(coalesce((select string_agg(t.x, E'\n' order by t.o) from jsonb_array_elements_text(a.antworten) with ordinality t(x, o)), '')) <> z.ma) then
      fehler := fehler || format('%s: Aufgabe %s (Einheit %s, Platz %s) ist nicht die erwartete (Fragetext/Typ/Lernkarte/Antworten)', z.k, a.id, z.e, z.r); continue; end if;
    -- Lösung samt Einheit und Toleranz wie eingespielt (jsonb-Gleichheit: Zahlen werden als Zahlen verglichen, 12 = 12.0)
    if a.loesung is distinct from z.o then
      fehler := fehler || format('%s: Aufgabe %s (Einheit %s, Platz %s): Lösung %s statt %s wie eingespielt', z.k, a.id, z.e, z.r, a.loesung, z.o); continue; end if;
    if a.id = any(v_ids) then fehler := fehler || format('%s: Aufgabe %s doppelt zugeordnet', z.k, a.id); continue; end if;
    v_ids := v_ids || a.id;
    if z.regel is not null then
      insert into schule.aufgabe_regel (aufgabe_id, regel) values (a.id, z.regel) on conflict do nothing;
      get diagnostics c = row_count; n_regel_neu := n_regel_neu + c;
      if (select r.regel from schule.aufgabe_regel r where r.aufgabe_id = a.id) is distinct from z.regel then
        fehler := fehler || format('%s: Aufgabe %s hat schon eine andere Regel', z.k, a.id); end if;
    end if;
    for f in select * from jsonb_array_elements(z.fb) loop
      insert into schule.aufgabe_fehlbild (aufgabe_id, nr, art, luecke, wert, beschreibung, fehlbild, regel)
      values (a.id, (f->>'nr')::smallint, f->>'art', (f->>'luecke')::smallint, f->>'wert', f->>'text', f->>'fehlbild', f->>'regel') on conflict do nothing;
      get diagnostics c = row_count; n_fb_neu := n_fb_neu + c;
      select * into v_alt from schule.aufgabe_fehlbild x where x.aufgabe_id = a.id and x.nr = (f->>'nr')::smallint;
      if v_alt.nr is null or (v_alt.art, v_alt.luecke, v_alt.wert, v_alt.beschreibung, v_alt.fehlbild, v_alt.regel)
           is distinct from (f->>'art', (f->>'luecke')::smallint, f->>'wert', f->>'text', f->>'fehlbild', f->>'regel') then
        fehler := fehler || format('%s: Fehlbild %s steht schon anders da (oder gleicher Schlüssel unter anderer Nummer)', z.k, f->>'nr'); continue; end if;
      v := schule.fehlbild_probeantwort(a, f->>'art', (f->>'luecke')::int, f->>'wert');
      b := schule.antwort_bewerten(a, v);
      if not coalesce((b->>'format_ok')::boolean, false) or coalesce((b->>'richtig')::boolean, true) then
        fehler := fehler || format('%s: Fehlbild %s – Antwort %s wird nicht als gültig und falsch bewertet (%s)', z.k, f->>'nr', v, b); continue; end if;
      if schule.fehlbild_finden(a, v) is distinct from (f->>'nr')::smallint then
        fehler := fehler || format('%s: Fehlbild %s wird an der Antwort %s nicht wiedererkannt', z.k, f->>'nr', v); end if;
    end loop;
    if (select count(*) from schule.aufgabe_fehlbild x where x.aufgabe_id = a.id) <> jsonb_array_length(z.fb) then
      fehler := fehler || format('%s: Aufgabe %s hat andere Fehlbilder in der Datenbank als im Paket', z.k, a.id); end if;
  end loop;
  if array_length(fehler, 1) > 0 then raise exception 'RB-S Regelbezug ABBRUCH, alles zurückgerollt (% Befunde): %', array_length(fehler, 1), array_to_string(fehler[1:40], ' | '); end if;
  if coalesce(array_length(v_ids, 1), 0) <> 116
     or (select count(*) from schule.aufgabe_regel where aufgabe_id = any(v_ids)) <> 116
     or (select count(*) from schule.aufgabe_fehlbild where aufgabe_id = any(v_ids)) <> 214 then
    raise exception 'RB-S Regelbezug ABBRUCH: Zählung stimmt nicht (Aufgaben %, erwartet 116)', array_length(v_ids, 1); end if;
  raise notice 'RB-S Regelbezug: % Aufgaben, % Regeln neu, % Fehlbilder neu (zweiter Lauf: 0 und 0)', array_length(v_ids, 1), n_regel_neu, n_fb_neu;
end $rbnach$;
